<template>
  <div class="email-page">
    <header><div><span>MEU SITE</span><h1>Meu E-mail</h1><p>Campanhas de saída com consentimento, descadastro e controle de velocidade.</p></div><button @click="load">Atualizar</button></header>
    <nav><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{ item.label }}</button></nav>
    <section v-if="tab==='resumo'" class="cards"><article><small>SMTP</small><strong>{{ settings.active ? 'Ativo' : 'Desativado' }}</strong><p>{{ settings.host || 'Não configurado' }}</p></article><article><small>Contatos autorizados</small><strong>{{ authorizedContacts }}</strong><p>{{ contacts.length }} cadastrados</p></article><article><small>Campanhas</small><strong>{{ campaigns.length }}</strong><p>{{ campaigns.filter(c=>c.status==='concluida').length }} concluídas</p></article></section>
    <form v-if="tab==='smtp'" class="panel form-grid" @submit.prevent="saveSettings">
      <div class="wide"><h2>Servidor SMTP de saída</h2><p>O Google continua recebendo os e-mails. Aqui configuramos somente os disparos.</p></div>
      <label>Servidor<input v-model="settings.host" required placeholder="smtp.gmail.com"></label><label>Porta<input v-model.number="settings.port" required type="number"></label><label>Segurança<select v-model="settings.encryption"><option value="tls">TLS</option><option value="ssl">SSL</option></select></label>
      <label>Usuário<input v-model="settings.username" autocomplete="off" placeholder="email@dominio.com.br"></label><label>Senha ou senha de app<input v-model="settings.password" autocomplete="new-password" type="password" placeholder="Deixe vazio para manter"></label><label>E-mail remetente<input v-model="settings.from_email" required type="email"></label><label>Nome remetente<input v-model="settings.from_name"></label><label>Responder para<input v-model="settings.reply_to" type="email"></label><label>Limite por minuto<input v-model.number="settings.rate_per_minute" min="1" max="500" type="number"></label>
      <label class="check wide"><input v-model="settings.active" type="checkbox"> Ativar disparos por este servidor</label><div class="wide actions"><button class="primary" type="submit">Salvar configuração</button></div>
    </form>
    <section v-if="tab==='contatos'" class="panel"><form class="inline-form" @submit.prevent="saveContact"><input v-model="contact.nome" placeholder="Nome"><input v-model="contact.email" required type="email" placeholder="E-mail"><input v-model="contact.origem_consentimento" required placeholder="Origem do consentimento"><button class="primary">Adicionar</button></form><p class="notice">Somente contatos que autorizaram comunicações devem ser adicionados.</p><div class="table"><div class="tr head"><span>Contato</span><span>Origem</span><span>Status</span></div><div v-for="c in contacts" :key="c.id" class="tr"><span><b>{{ c.nome || 'Sem nome' }}</b><small>{{ c.email }}</small></span><span>{{ c.origem_consentimento }}</span><span>{{ c.descadastrado_em ? 'Descadastrado' : c.ativo ? 'Ativo' : 'Inativo' }}</span></div></div></section>
    <section v-if="tab==='modelos'" class="panel two-cols"><form @submit.prevent="saveTemplate"><h2>Novo modelo</h2><label>Nome<input v-model="template.nome" required></label><label>Assunto<input v-model="template.assunto" required></label><label>HTML<textarea v-model="template.html" required rows="12"></textarea></label><p class="notice">Variáveis: nome, empresa, cidade, email e descadastro_url entre chaves duplas.</p><button class="primary">Salvar modelo</button></form><div><h2>Modelos salvos</h2><button v-for="t in templates" :key="t.id" class="list-item" @click="useTemplate(t)"><b>{{ t.nome }}</b><small>{{ t.assunto }}</small></button></div></section>
    <section v-if="tab==='campanhas'" class="panel two-cols"><form @submit.prevent="saveCampaign"><h2>Nova campanha</h2><label>Nome<input v-model="campaign.nome" required></label><label>Modelo<select v-model="campaign.template_id" @change="selectTemplate"><option value="">Sem modelo</option><option v-for="t in templates" :key="t.id" :value="t.id">{{ t.nome }}</option></select></label><label>Assunto<input v-model="campaign.assunto" required></label><label>HTML<textarea v-model="campaign.html" required rows="10"></textarea></label><label>Agendar (opcional)<input v-model="campaign.agendada_para" type="datetime-local"></label><button class="primary">Criar rascunho</button></form><div><h2>Histórico</h2><article v-for="c in campaigns" :key="c.id" class="campaign"><div><b>{{ c.nome }}</b><small>{{ c.status }} · {{ c.enviados || 0 }}/{{ c.total || 0 }} enviados · {{ c.falhas || 0 }} falhas</small></div><button v-if="c.status==='rascunho'" @click="queueCampaign(c)">Enfileirar</button></article></div></section>
    <p v-if="message" class="feedback">{{ message }}</p>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import api from '@/services/api'
const tabs=[{id:'resumo',label:'Visão geral'},{id:'smtp',label:'Configuração SMTP'},{id:'contatos',label:'Contatos'},{id:'modelos',label:'Modelos'},{id:'campanhas',label:'Campanhas'}],tab=ref('resumo'),message=ref(''),contacts=ref([]),templates=ref([]),campaigns=ref([])
const settings=reactive({host:'smtp.gmail.com',port:587,encryption:'tls',username:'',password:'',from_email:'',from_name:'IntelbrasTech',reply_to:'',rate_per_minute:20,active:false}),contact=reactive({nome:'',email:'',origem_consentimento:'',consentimento:true,ativo:true}),template=reactive({nome:'',assunto:'',html:'',ativo:true}),campaign=reactive({nome:'',assunto:'',html:'',template_id:'',agendada_para:''})
const authorizedContacts=computed(()=>contacts.value.filter(c=>c.ativo&&c.consentimento&&!c.descadastrado_em).length)
async function load(){const {data}=await api.get('/email-marketing');Object.assign(settings,data.settings||{});contacts.value=data.contacts||[];templates.value=data.templates||[];campaigns.value=data.campaigns||[]}
function notify(t){message.value=t;setTimeout(()=>message.value='',5000)}
async function saveSettings(){const p={...settings};if(p.username?.includes('•'))p.username='';if(p.password?.includes('•'))p.password='';const {data}=await api.put('/email-marketing/configuracao',p);Object.assign(settings,data.settings);notify(data.message)}
async function saveContact(){const {data}=await api.post('/email-marketing/contatos',contact);Object.assign(contact,{nome:'',email:'',origem_consentimento:'',consentimento:true,ativo:true});notify(data.message);await load()}
async function saveTemplate(){const {data}=await api.post('/email-marketing/modelos',template);Object.assign(template,{nome:'',assunto:'',html:'',ativo:true});notify(data.message);await load()}
function useTemplate(t){Object.assign(template,{nome:t.nome,assunto:t.assunto,html:t.html,ativo:Boolean(t.ativo)})} function selectTemplate(){const t=templates.value.find(i=>i.id===Number(campaign.template_id));if(t)Object.assign(campaign,{assunto:t.assunto,html:t.html})}
async function saveCampaign(){const p={...campaign,template_id:campaign.template_id||null,agendada_para:campaign.agendada_para||null},{data}=await api.post('/email-marketing/campanhas',p);Object.assign(campaign,{nome:'',assunto:'',html:'',template_id:'',agendada_para:''});notify(data.message);await load()}
async function queueCampaign(c){if(!confirm(`Enviar "${c.nome}" para ${authorizedContacts.value} contatos autorizados?`))return;const {data}=await api.post(`/email-marketing/campanhas/${c.id}/enfileirar`);notify(`${data.message} ${data.total} destinatários.`);await load()} onMounted(load)
</script>
<style scoped>
.email-page{max-width:1380px;margin:auto;padding:26px;color:#e8edf7}.email-page>header{display:flex;justify-content:space-between;align-items:center}.email-page>header span{font-size:10px;font-weight:850;letter-spacing:.13em;color:#748dff}.email-page h1{font-size:30px;font-weight:900}.email-page h2{font-size:17px;font-weight:850;margin-bottom:14px}.email-page p,.email-page small{color:#8995aa}.email-page button{border:1px solid #333a55;border-radius:8px;padding:9px 13px;font-weight:750}nav{display:flex;gap:7px;margin:22px 0;overflow:auto}nav button.active,.primary{background:#625df5!important;border-color:#625df5!important;color:white}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.cards article,.panel{background:#111424;border:1px solid #282e45;border-radius:14px;padding:20px}.cards strong{display:block;font-size:24px;margin:7px 0}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.wide{grid-column:1/-1}label{display:flex;flex-direction:column;gap:7px;color:#aab3c5;font-size:12px;font-weight:700}input,select,textarea{width:100%;background:#0b0e1b;border:1px solid #303650;border-radius:8px;padding:11px;color:#f1f4fb}.check{flex-direction:row;align-items:center}.check input{width:auto}.actions{text-align:right}.inline-form{display:grid;grid-template-columns:1fr 1.4fr 1fr auto;gap:10px}.notice{font-size:11px;margin:12px 0}.tr{display:grid;grid-template-columns:2fr 1fr .7fr;gap:12px;padding:12px;border-top:1px solid #282e45;font-size:12px}.tr span:first-child small,.list-item small,.campaign small{display:block}.head{color:#77849a;font-size:10px;font-weight:800}.two-cols{display:grid;grid-template-columns:1fr 1fr;gap:28px}.two-cols form label{margin-bottom:12px}.list-item{display:block;width:100%;text-align:left;margin-bottom:8px}.campaign{display:flex;justify-content:space-between;align-items:center;border:1px solid #293049;border-radius:9px;padding:12px;margin-bottom:9px}.feedback{position:fixed;right:24px;bottom:24px;background:#166c4b;color:white!important;padding:13px 18px;border-radius:9px}@media(max-width:800px){.email-page{padding:15px}.cards,.form-grid,.two-cols,.inline-form{grid-template-columns:1fr}.wide{grid-column:auto}.tr{grid-template-columns:1fr}.head{display:none}}
</style>
